use std::sync::{Arc, Mutex};
use std::thread;

struct ThreadSafeCounter {
    count: Arc<Mutex<u64>>,
}

impl ThreadSafeCounter {
    fn new() -> Self {
        Self { count: Arc::new(Mutex::new(0)) }
    }

    fn increment(&self) {
        let mut num = self.count.lock().unwrap();
        *num += 1;
    }

    fn get(&self) -> u64 {
        *self.count.lock().unwrap()
    }
}
```
